<template><div class="app-container"><el-table v-loading="loading" :data="rows"><el-table-column prop="title" label="标题"/><el-table-column prop="imageUrl" label="图片" width="90"><template #default="s"><image-preview :src="s.row.imageUrl" :width="42" :height="42"/></template></el-table-column><el-table-column prop="jumpType" label="跳转类型"/><el-table-column prop="beginTime" label="展示开始" width="180"><template #default="s">{{parseTime(s.row.beginTime)}}</template></el-table-column><el-table-column prop="endTime" label="展示结束" width="180"><template #default="s">{{parseTime(s.row.endTime)}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="toggle(s.row)">{{s.row.status==='0'?'停用':'启用'}}</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></div></template><script setup name="ShopBanner">import{ref,getCurrentInstance}from'vue';import{changeBannerStatus,deleteBanner,listBanner}from'@/api/shop/banner';const{proxy}=getCurrentInstance(),loading=ref(false),rows=ref([]);function load(){loading.value=true;listBanner().then(r=>rows.value=r.rows).finally(()=>loading.value=false)}function toggle(r){changeBannerStatus(r.bannerId,r.status==='0'?'1':'0').then(load)}function remove(r){proxy.$modal.confirm(`确认删除“${r.title}”？`).then(()=>deleteBanner(r.bannerId)).then(load).catch(()=>{})}load()</script>
